exercises.solution:
export const PPM = 1_000_000;

export function seriesPpm(parts) {
  return parts.reduce((acc, p) => (acc * p) / PPM, PPM);
}

export function parallelPpm(parts) {
  const allDown = parts.reduce((acc, p) => (acc * (PPM - p)) / PPM, PPM);
  return PPM - allDown;
}

