exercises.solution:
export const MINUTES_PER_MONTH = 43_200;

export function downtimeMinutesPerMonth(availabilityPpm) {
  return Math.floor((MINUTES_PER_MONTH * (1_000_000 - availabilityPpm)) / 1_000_000);
}

export function budgetLeftMinutes(availabilityPpm, usedMinutes) {
  return Math.max(0, downtimeMinutesPerMonth(availabilityPpm) - usedMinutes);
}

