export function backoffMs(baseMs, capMs, attempt) {
  return Math.min(capMs, baseMs * 2 ** attempt);
}

export function backoffSchedule(baseMs, capMs, retries) {
  return Array.from({ length: retries }, (_, attempt) => backoffMs(baseMs, capMs, attempt));
}

