exercises.solution:
const backoff = (baseMs, capMs, attempt) => Math.min(capMs, baseMs * 2 ** attempt);

export function fullJitterBounds(baseMs, capMs, attempt) {
  return { min: 0, max: backoff(baseMs, capMs, attempt) };
}

export function equalJitterBounds(baseMs, capMs, attempt) {
  const b = backoff(baseMs, capMs, attempt);
  return { min: Math.floor(b / 2), max: b };
}

