exercises.solution:
export function worstCaseTotalMs(timeoutMs, retries, baseMs, capMs) {
  let total = (retries + 1) * timeoutMs;
  for (let i = 0; i < retries; i++) total += Math.min(capMs, baseMs * 2 ** i);
  return total;
}

export function maxRetriesWithin(deadlineMs, timeoutMs, baseMs, capMs) {
  let r = 0;
  while (worstCaseTotalMs(timeoutMs, r + 1, baseMs, capMs) <= deadlineMs) r++;
  return r;
}

