export function availabilityPpm(mtbfHours, mttrHours) {
  return (mtbfHours * 1_000_000) / (mtbfHours + mttrHours);
}

export function maxMttrMinutes(mtbfHours, targetPpm) {
  return Math.floor((mtbfHours * 60 * (1_000_000 - targetPpm)) / targetPpm);
}

