exercises.solution:
export function maxStaleReadMs(n, r, w, lagMs) {
  return r + w > n ? 0 : lagMs;
}

export function staleWindowReads(n, r, w, lagMs, readQps) {
  return (readQps * maxStaleReadMs(n, r, w, lagMs)) / 1000;
}
